{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this production plan — for example, maximize the total number of complete products that can be assembled, maximize total profit (if so, what is the profit per unit of each component or per finished product), or something else?"
  ],
  "rationale": "The response asks for a single policy choice (the objective function). The parenthetical clause is a conditional follow-up that only applies if the user selects 'maximize total profit,' so it does not constitute a separate independent question that must be answered regardless of the primary choice."
}

